    'register_pause_activate_and_remove_hooks_endpoints_that_17dc8c62' => 'Hook\'ları kaydetme, duraklatma, etkinleştirme ve kaldırma. Bu uç noktalar token\'lara beyan ekleyebilir veya oturum açmayı reddedebilir.',
    'create_disable_resume_and_delete_audit_log_streams_a_ge_d507a36c' => 'Denetim günlüğü akışları oluşturma, devre dışı bırakma, sürdürme ve silme. Oluşturulan imzalama anahtarı yalnızca bir kez gösterilir.',
    'record_audit_events_your_app_s_users_cause_for_the_orga_a94adc1d' => 'Uygulamanızın kullanıcılarının oluşturduğu denetim olaylarını, gerçekleştiği kuruluşlar için kaydetme. Yalnızca olay gönderen bir arka ucun ihtiyaç duyduğu yetkiler.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Uygulamanızın gönderdiği denetim olaylarını ve dışa aktarımlarını okuma, kuruluşun zincirini doğrulama, uygulanan şemaları ve saklama kurallarını görüntüleme.',
    'start_csv_exports_of_the_audit_events_your_app_sent_the_230b66c5' => 'Uygulamanızın gönderdiği denetim olaylarını CSV olarak dışa aktarmayı başlatma; okuma kapsamının listelediği aynı olaylar tek dosyada sunulur.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Denetim olaylarının doğrulandığı şemaları tanımlama, değiştirme ve silme; saklama süresini değiştirme. Saklama süresinin kısaltılması eski olayları kalıcı olarak siler.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Yetkilendirme şemasını ve ilişki demetlerini okuma, erişim kontrolleri ve liste sorguları çalıştırma: “Bu kullanıcı bu belgeyi düzenleyebilir mi?”, “Hangi belgeleri görebilir?”. Yalnızca uygulamanın arka ucunun erişim kurallarını uygulamak için ihtiyaç duyduğu yetkiler.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'İlişki demetlerini yazma ve silme: uygulamanızın hangi kaynaklarına kimin sahip olduğu, bunları kimin düzenleyebileceği veya görüntüleyebileceği. Yazma işlemi, uygulamanızdaki erişimi anında verir veya geri alır.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Yetkilendirme şemasını değiştirme: kaynak türleri ve her ilişkinin nasıl değerlendirildiği. Bu ortamdaki tüm kontrollerin yanıtını aynı anda değiştirir.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Kimlik doğrulama politikasını, sosyal oturum açma sağlayıcılarını ve eski oturum açma bildirimini okuma; sağlayıcı sırları hiçbir zaman gösterilmez.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Parola, MFA ve SSO kurallarını, kullanıcıların kendi kendine kaydolmasını, sosyal oturum açma sağlayıcılarını ve eski oturum açma onayını değiştirme.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Radar modunu, yerleşik ve özel kuralları, izin ve engelleme listelerini ve karar inceleyicisini görüntüleme: oturum açma veya kaydolmanın neden kabul edildiği, ek doğrulamaya tabi tutulduğu ya da engellendiği. Kararlardaki IP veya diğer adresler hiçbir zaman gösterilmez.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Radar kurallarını oluşturma, yeniden sıralama ve silme; yerleşik kuralları ayarlama; izin ve engelleme listelerine kayıt ekleme veya listelerden kayıt kaldırma.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Radar\'ı izleme (yalnızca kayıt) ve uygulama (engelleme ve ek doğrulama) modları arasında değiştirme; ortamın oturum açma korumasını açma veya kapatma.',
    'list_the_publishable_keys_browser_apps_present_to_the_f_9a4fe3ce' => 'Tarayıcı uygulamalarının Frontend API\'ye sunduğu yayımlanabilir anahtarları ve izin verilen kökenlerini listeleme.',
    'create_publishable_keys_change_which_origins_may_presen_79684ec2' => 'Yayımlanabilir anahtar oluşturma, bunları kullanabilen kökenleri değiştirme ve anahtarları iptal etme.',
    'list_the_applications_that_trust_this_environment_as_th_61538b0b' => 'Bu ortama SAML kimlik sağlayıcısı olarak güvenen uygulamaları listeleme; sertifikaları hiçbir zaman gösterilmez.',
    'register_change_and_remove_the_applications_people_sign_6b6a4041' => 'Kullanıcıların buradaki hesaplarıyla oturum açtıkları uygulamaları kaydetme, değiştirme ve kaldırma.',
    'read_the_hosted_sign_in_theme_and_branding_of_the_envir_c85a3622' => 'Ortamın ve kuruluşlarının barındırılan oturum açma temasını ve marka görünümünü görüntüleme.',
    'change_the_hosted_sign_in_theme_and_branding_of_the_env_bc832c7e' => 'Ortamın ve kuruluşlarının barındırılan oturum açma temasını ve marka görünümünü değiştirme.',
    'read_this_environment_s_custom_domain_and_the_dns_recor_4408e8a7' => 'Bu ortamın özel alan adını ve onu doğrulayan DNS kaydını görüntüleme.',
    'add_verify_and_remove_the_custom_domain_this_environmen_9a4835eb' => 'Bu ortamın sunulduğu özel alan adını ekleme, doğrulama ve kaldırma.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Bir kişiyi kalıcı olarak silme (GDPR Madde 17): kimlik bilgileri, oturumları, üyelikleri ve kişisel verileri silinir; hesabı takma adlandırılır. Geri alınamaz.',
    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Rol oluşturma, yeniden adlandırma, izinlerini değiştirme ve silme; rolleri oluşturan elle tanımlanmış izinleri yazma. Kişilere rol atama işlemi `roles:write` kapsamındadır.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Kuruluşların oturum açmak için kullandığı SAML ve OIDC bağlantılarını ve kullanıcıları bu bağlantılara yönlendiren e-posta alan adlarını listeleme; sertifika, istemci sırrı veya imzalama anahtarı hiçbir zaman gösterilmez.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'SSO bağlantıları oluşturma, değiştirme, etkinleştirme, devre dışı bırakma ve silme; bir kuruluş için SSO\'yu zorunlu kılma; e-posta alan adlarını doğrulama ve bu alanlarda SSO\'yu zorunlu kılma. Kullanıcıların oturum açma biçimini değiştirir.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Kullanıcıları ortama eşitleyen dizinleri (SCIM, Google Workspace, Microsoft Entra), gruplarını ve eşitleme hatalarını listeleme; bearer token veya sağlayıcı kimlik bilgileri hiçbir zaman gösterilmez.',
    'connect_rename_pause_re_key_and_delete_inbound_director_9cb4cce4' => 'Gelen dizinleri bağlama, yeniden adlandırma, duraklatma, anahtarlarını yenileme ve silme; gruplarını rollerle eşleme. Yeni veya yenilenen SCIM bearer token yalnızca bir kez gösterilir.',
    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Bu ortamın kullanıcı gönderdiği hedef SCIM sistemlerini ve hata durumlarını listeleme; kimlik bilgileri hiçbir zaman gösterilmez.',
    'register_pause_resume_and_delete_the_scim_targets_this_ca3c3bb1' => 'Bu ortamın kullanıcı verilerini gönderdiği SCIM hedeflerini kaydetme, duraklatma, sürdürme ve silme.',
    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Rol çakışması (görevler ayrılığı) kurallarını ve erişim incelemelerini, onaylanması istenen tüm öğelerle birlikte görüntüleme.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Rol çakışması kurallarını tanımlama, açma, kapatma ve kaldırma; erişim incelemeleri açma, kararları kaydetme ve incelemeleri kapatma. Kapatma işlemi tüm erişim iptallerini uygular.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Token kasasında saklanan hedef sistem kimlik bilgilerini ve her birine hangi uygulamaların geçici erişim alabileceğini listeleme; saklanan değerler hiçbir zaman gösterilmez.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Hedef sistem kimlik bilgilerini saklama, yenileme ve iptal etme; uygulamaya bunlara geçici erişim hakkı verme veya bu hakkı geri alma. Uygulamanın kendi token\'ındaki vault.manage / vault.lease kapsamları değildir.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Özellik bayraklarını hedeflemeleriyle birlikte listeleme ve her bayrağı bir kuruluştaki kullanıcı için değerlendirme; uygulamanın arka ucunun elinde token olmadığında sorguladığı bilgiler.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Özellik bayraklarını tanımlama, açma, kapatma, yeniden hedefleme ve silme; hangi kullanıcı ve kuruluşların hangi özelliklere sahip olacağını belirleme.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Kullanıcıların hesaplarını bağlayabileceği üçüncü taraf sağlayıcıları, bu token\'lara geçici erişim alabilecek uygulamaları ve hesap bağlayan kullanıcıları listeleme; istemci sırrı veya token hiçbir zaman gösterilmez.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Pipe bağlantılarını yapılandırma, değiştirme ve kaldırma; uygulamaya kullanıcıların bağlı hesap token\'larına geçici erişim hakkı verme veya bu hakkı geri alma; kullanıcının hesap bağlantısını kesme.',
    'list_an_organization_s_recent_admin_portal_links_what_e_f1c55153' => 'Kuruluşun son Yönetici Portalı bağlantılarının ne açtığını, kim tarafından oluşturulduğunu, kime e-postayla gönderildiğini ve durumunu listeleme; bağlantının kendisi hiçbir zaman gösterilmez.',
