    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Yeni bir parola oluşturmak yerine mevcut hesabını kullanmayı tercih edenler için giriş sayfasında Google, GitHub, Apple ve diğer sağlayıcıların düğmelerini sunar. Sağlayıcıyı ortam için bir kez yapılandırın; tüm kuruluşlar kullanabilsin. Bir kuruluş kendi erişim bilgilerini kullanabilir veya sağlayıcıyı kapatabilir. Siz erişim bilgilerini girersiniz; diğer alanlar otomatik doldurulur. Sağlayıcının gönderdiği e-posta adresi tek başına burada mevcut olan bir hesaba erişmek için asla yeterli değildir.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per_42243556' => 'Kodunuzun Cbox ID için kullandığı anahtarlar, her tür için ayrı sekmede gösterilir. Gizli anahtar, diğer adıyla yönetim anahtarı, backendinizin bir ortamdaki kuruluşları, üyeleri, davetleri, rolleri ve uygulamaları yönetmesini sağlar. Çalışma alanı anahtarı, yerleşik bir rolle çalışma alanı API’sini çağırır. Yayımlanabilir anahtar tarayıcı uygulamasında kullanılır ve yalnızca izin verdiğiniz kaynaklardan çalışır. Gizli anahtarlar ve çalışma alanı anahtarları yalnızca bir kez gösterilir. Oluştururken kopyalayın ve sızmaları durumunda hemen iptal edin.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Bu ortamı SAML kimlik sağlayıcısı olarak kabul eden uygulamaları kaydeder; böylece kullanıcılar burada mevcut hesaplarıyla giriş yapar. Her uygulamaya ait olduğu kuruluşu atayın; yalnızca o kuruluşun üyeleri giriş yapabilsin. Kuruluş atanmamış uygulama, ortamdaki tüm kullanıcılara açıktır. Bu dışa yönelik bağlantıdır. Başka bir sistemdeki şirket hesabıyla girişe izin vermek için Kimlik doğrulama altındaki Kurumsal SSO bölümünü kullanın.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Geliştirmede kullandığınız frameworkü seçin. Yerel geliştirme sunucunuza yönlendirme, yapıştırılacak ortam yapılandırması ve kullanıcı giriş koduyla bir uygulama oluşturulur. Sayfa gerçek bir giriş yapılmasını bekler. Altında ürünü hazırlama adımları bulunur: marka görünümü, kuruluşlar, tek oturum açma, ajan, ekip arkadaşı ve üretim ortamı. Adımlar elle değil, ortamın gerçek durumuna göre tamamlandı olarak işaretlenir.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar her giriş ve kaydı değerlendirir: çalınmış erişim bilgileriyle denemeler, bot benzeri hız, imkânsız seyahat, yeni cihazlar, anonimleştirme ağları ve geçici adresler; ayrıca kendi kurallarınız, izin ve engel listeleriniz. Her kararı kaydeder; kuralları uygulamayı açtığınızda erişimi engeller veya ikinci faktör ister. Kuralları uygulamadan önce ve bir kullanıcı giriş yapamadığını bildirdiğinde kararları buradan inceleyin.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Uygulamaların, bir kuruluştaki belirli bir kişi için sorguladığı özellik anahtarları. Özelliği belirli kullanıcılara, kuruluşlara veya tüm kullanıcıların bir bölümüne açın. Her uygulama belirteçten veya API’den aynı yanıtı okur.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Bu ortamda yönetim anahtarıyla işlem yapan yazılımlar: Claude Code, Cursor, kurum içi bir bot veya kendi backend’iniz. Her biri yalnızca verdiğiniz yetki kapsamlarına sahiptir ve onay istediğiniz durumlarda onayınızı bekler.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Alıcı aynı gizli anahtarı kullanır. 64 karakterlik onaltılık gizli anahtar, whsec_ ve ardından bu onaltılık dizenin base64 kodlamasına dönüşür: "whsec_" + base64(secret). Zaten whsec_ ile başlayan gizli anahtar olduğu gibi kullanılır.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Bu kurulumdaki tüm ortamlara ait kuruluşlar, kullanıcılar ve etkin oturumlar ile en fazla üyeye sahip kuruluşlar. Bu görünüm yalnızca veri okur; konsolda seçili ortamı hiçbir zaman değiştirmez.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Bu kuruluşa giriş yapabilen herkes ve gönderdiğiniz, henüz kabul edilmemiş davetler. Kişileri e-postayla davet edin; kendi giriş yöntemlerini kendileri ayarlar, böylece başkasının parolasıyla uğraşmazsınız.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Kişilerin mevcut bir hesapla giriş yapmasına izin verin. Sağlayıcıyı ortam için bir kez ayarlayın; tüm kuruluşlarda kullanılabilir olur. Bir kuruluş kendi kimlik bilgilerini kullanabilir veya bir sağlayıcıyı kapatabilir.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar her giriş ve kayıt işlemini değerlendirir: çalıntı kimlik bilgileriyle yapılan denemeler, botlara özgü hız, imkânsız seyahat, yeni cihazlar, anonimleştirici ağlar, geçici adresler ve kendi kurallarınızla listeleriniz. Kararın nedenini de kaydeder.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Bu kullanıcı artık bu ortamdaki hiçbir uygulamaya giriş yapamaz. Mevcut oturumları bir sonraki istekte çalışmayı durdurur. Kayıtları korunur ve kullanıcıyı istediğiniz zaman yeniden etkinleştirebilirsiniz.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Değerlendirme sırası: engelleme listesi, izin listesi, yukarıdan aşağıya kendi kurallarınız (ilk eşleşen karar verir), ardından yerleşik kurallar (tetiklenenlerin en katısı karar verir). Hiçbir eşleşme yoksa erişime izin verilir.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Çoğu entegrasyon için webhook kullanın: bunlar olaydan sonra çalışır ve işlemi bekletemez. Yalnızca sisteminizin giriş sırasında veya token verilirken karara katılması gerekiyorsa hook kullanın.',
