    'everything_a_role_can_be_allowed_to_do_write_your_own_b_233ea6c4' => 'Bir role izin verilebilecek tüm işlemler. Aşağıda kod yazmadan kendi izinlerinizi oluşturun veya uygulamalarınızın kendi izinlerini otomatik kaydetmesini sağlayın.',
    'face_id_touch_id_windows_hello_or_a_security_key_turnin_6e23006c' => 'Face ID, Touch ID, Windows Hello veya güvenlik anahtarı. Kapatıldığında mevcut geçiş anahtarları korunur; yeniden açtığınızda kullanılabilirler.',
    'filter_the_list_to_one_organization_to_scan_it_for_peop_6dbcc13b' => 'Çakışan rol çiftlerine sahip kişileri taramak için listeyi tek bir kuruluşa göre filtreleyin. Henüz kontrol yapılmadı.',
    'for_a_secret_that_has_leaked_anything_still_using_it_fa_7b1c0246' => 'Sızmış bir gizli anahtar için. Onu kullanan her şey hemen çalışmayı durdurur.',
    'for_development_refused_on_anything_but_the_origins_you_113f24ad' => 'Geliştirme için. Canlı ortamda olduğu gibi yalnızca listelediğiniz kaynaklardan kabul edilir.',
    'give_your_app_the_feature_flags_scope_and_read_the_feat_a6908f11' => 'Uygulamanıza feature_flags kapsamını verin ve belirtecindeki feature_flags alanını okuyun.',
    'give_your_apps_those_scopes_on_their_scopes_tab_tokens_97d115cd' => 'Uygulamalarınıza bu kapsamları Kapsamlar sekmesinden verin; belirteçleri hedef kitle olarak API\'yi belirtir.',
    'grants_that_would_break_this_rule_are_blocked_from_now_1454bf59' => 'Bu kuralı ihlal edecek atamalar artık engellenir. Çift role zaten sahip olanlar rollerini korur; onları yukarıdaki taramayla bulabilirsiniz.',
    'have_the_app_declare_the_roles_it_understands_so_you_ca_9074afe0' => 'Buradan atayabilmek için uygulamanın desteklediği rolleri bildirmesini sağlayın.',
    'holds_conflicting_roles_part1_part2_23b385ca' => 'Çakışan roller: :part1 :part2',
    'holds_part1_part2_6b1a0140' => 'Sahip olduğu roller: :part1 :part2',
    'how_an_app_connects_is_fixed_at_registration_changing_i_0372baec' => 'Uygulamanın bağlantı biçimi kayıt sırasında belirlenir. Değiştirmek kimlik bilgilerinin anlamını değiştirir; bu uygulamayı başka amaçla kullanmak yerine yenisini kaydedin.',
    'how_long_an_access_token_for_this_app_is_acc_22748384' => 'Bu uygulamanın erişim tokenının ne kadar süre kabul edileceği. Daha kısa süreler, tokenları çevrimdışı doğrulayan bir uygulamanın iptal edilmiş bir tokenı ne kadar süre kabul edebileceğini sınırlar. İntrospeksiyon kullanan uygulamalar iptali hemen tespit edebilir. Yenileme tokenları, erişim tokenları yenilenirken kullanıcıların oturumlarını açık tutar.',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Kişilerin :part1 için oturum açma biçimi. Başlangıçta ortam varsayılanları kullanılır; buradaki değişiklikler bunları yalnızca sıkılaştırabilir.',
    'https_app_example_com_https_staging_example__ad77bfc7' => 'https://app.example.com
https://staging.example.com',
    'inherited_46b2e93c' => 'devralınan',
    'invoices_create_be35ad14' => 'invoices:create',
    'invoices_read_459482fd' => 'invoices:read',
    'its_rules_go_with_it_apps_asking_for_its_key_get_off_fr_aacd29e9' => 'Kuralları da silinir. Anahtarını sorgulayan uygulamalar artık kapalı yanıtı alır; verilmiş belirteçler süreleri dolana kadar onu taşır.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Kapsamları da silinir. Uygulamalarda elle girilmiş kapsam olarak kalırlar ancak artık bu API\'ye erişim sağlamazlar; verilmiş belirteçler süreleri dolana kadar çalışır.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Bir ortamın yönetim API’si için anahtarlar: ortamın kuruluşlarını, üyelerini, davetlerini, rollerini ve uygulamalarını kendi backend’inizden yönetin. Her anahtarın açıkça belirtilmiş yetki kapsamları vardır.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Bir tokendaki roller ve izinler, belirli bir andaki durumu gösterir. Korunan her işlemden önce Cbox ID’dan güncel bir erişim kararı alın ve uygulamanızda ilgili kaynağa erişimi denetleyin. Token içeriği tek başına daha sonra geri alınan erişim haklarını yansıtmaz:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Kendi giriş yöntemleriniz ve etkin oturumlarınız. Geçiş anahtarı en güvenli ve en hızlı seçenektir: cihazınız anahtarı parmak izi veya yüz tanımayla açar; kimlik avıyla çalınabilecek bir parola kalmaz.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Her eylem, uygulamanızın gönderdiği biçimde kabul edilir. Bir eyleme şema ekleyerek olaylarının geldiğinde doğrulanmasını sağlayın. Tutarlı bir günlük, olay okunurken değil yazılırken oluşturulur.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Bir uygulamanın yapılandırmasında veya ortam dosyasında bulunan her API anahtarı, merkezi olarak değiştiremeyeceğiniz veya hızla geri alamayacağınız bir anahtardır. Burada saklandığında şifrelenir, uygulama bazında erişim verilir ve tek tıklamayla iptal edilebilir.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Düğme artık görünmez ve kimlik bilgileri silinir. Bu sağlayıcıyla giriş yapanlar hesaplarını korur ve parolalarını kullanmaya devam edebilir. Kimlik bilgilerini korumak için sağlayıcıyı silmek yerine kapatın.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Ters yön: Cbox ID, kişilerinizi şirketinizin kullandığı diğer SaaS ürünlerine bu ürünlerin SCIM uç noktaları üzerinden aktarır. Her sağlayıcı için ayrı bir yönetim paneli yerine, erişim verme ve kaldırma işlemleri için tek bir yer.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Kuruluşu, sahibini, ilk ürünü ve bu ürünün üretim ortamını oluşturur. Kuruluş sahibine kendi parolasını belirlemesi için e-postayla bağlantı gönderilir; parolayı onun yerine siz seçmezsiniz.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Şu anda birisi burada kişileri elle ekleyip kaldırıyor. Şirketinizin zaten yönettiği dizini bağlayın; en çok unutulan işlem olan kaldırmalar da dahil olmak üzere her ikisi otomatik yapılsın.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Verdiği tüm tokenlar şimdi iptal edilir ve yeni girişlerde artık kullanılamaz. Tokenları kendisi doğrulayan bir uygulama, süreleri dolduğunda bunları kabul etmeyi bırakır; bu süre oturumun kendi bitişini aşamaz.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Başka bir sistemden geçiş yaparken uygulamanız, eski giriş sisteminin yerini rol tanımlarının yanında kendi bildiriminde belirtebilir. Herhangi bir işlem yapmadan önce onaylamanız için burada görünür.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Kullanıcılarınız hakkında bildiklerinize göre izin veren, ek doğrulama isteyen veya engelleyen bir kural yazın. Faaliyet göstermediğiniz ülkelerden girişlerde ek doğrulama isteyin veya ofis ağınızı sıklık kurallarından muaf tutun.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Sahibi olduğunuz bir alan adını, örneğin acme.com’u doğrulamak, Cbox ID’nin kişilerinizi e-posta adreslerinden tanıyıp doğrudan sağlayıcınıza yönlendirmesini sağlar. Böylece kimsenin doğru giriş düğmesini seçmesi gerekmez.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Hizmet sağlayıcı meta verilerini içe aktaran bir kimlik sağlayıcısı, varlık kimliğini ve ACS URL’sini ayrı ayrı almak yerine bu URL’yi kullanır. Kimlik sağlayıcısı tarafındaki ayarlar doldurulmadan önce de çalışır.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Bu işlem geri alınamaz. Kimlik bilgileri, üyelikler ve kişisel veriler silinir; hesap takma adlandırılır. Kişi bir kuruluşun tek sahibiyse önce sahipliği devredin.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Bu kişi olarak, onun oturumunda ve erişim yetkileriyle işlem yaparsınız. Süre 30 dakika ile sınırlıdır ve konsolun uygulayabildiği yerlerde erişim salt okunurdur. Her istek sizin adınıza kaydedilir.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Bu sayfanın yaptığı tek değişiklik askıya almadır ve geri alınabilir. Bir ortamı seçip açmak yalnızca konsolun görünümünü değiştirir; iki ortamda da hiçbir şeyi değiştirmez.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Şu anda kişiler burada saklanan kimlik bilgileriyle giriş yapıyor. Sağlayıcınızı bağlayın; mevcut şirket hesaplarını kullansınlar ve hesabı orada devre dışı bıraktığınız anda buradaki erişimleri de sona ersin.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Yeni gizli anahtar verilmez. Yeniden denemeler dahil bir sonraki girişimden itibaren teslimatlar diğer şemanın başlıklarını taşır. Güncellenmemiş bir alıcı bunların tümünü reddeder.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'E-postayla gönderilmediyse bu tek kullanımlık bağlantıyı kimlik sağlayıcılarını yöneten kişiye iletin. Süresi dolana kadar hesap gerektirmeden çalışır. Şimdi kopyalayın; yalnızca bir kez gösterilir.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Bu ortamda bir kişinin izin vermesini bekleyen yazılımlar. Anahtarı onay gerektiren bir ajan durur ve anahtarı oluşturan kişiye sorar. Buradan veya telefonunuzdan yanıtlayın.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Kuruluş; kullanıcıları, giriş yöntemlerini ve rolleri bir araya getirir. Yukarıdan bir kuruluş oluşturun veya Ortamlar ekranından ortamın ilk kuruluşunu ve yöneticisini kurun.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'İçinde erişim vermek için kişiyi aşağıdaki kuruluşlardan birine ekleyin. Uygulamalarınızın kendi kuruluş ayrımı yoksa, bu ortamın tamamında geçerli bir yönetim ve destek rolü verin.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Yönetim ve destek rolü, kendi çalışanlarınıza tüm ortam için verdiğiniz bir roldür. Her kuruluşta geçerlidir ve hiçbir kuruluşun yöneticisi bu rolü göremez veya değiştiremez.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Bir uygulama veya ajan sizin adınıza işlem yapmak için onayınıza ihtiyaç duyduğunda istekler burada otomatik olarak görünür. O zamana kadar yapmanız gereken bir şey yoktur. Başlatmadığınız bir istek görürseniz reddedin.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS en zayıf ikinci faktördür: telefon numaranızı ele geçiren biri kodlarınızı alır. Kimlik doğrulama uygulaması veya geçiş anahtarını tercih edin; SMS’i yalnızca bunları kullanamıyorsanız kullanın.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Ortamınızın varsayılan marka görünümü: barındırılan giriş sayfasının görünümü, logosu ve favicon’u ile kullanıcıların gördüğü ad ve gönderen. Her kuruluş kendi ayarlarını belirlemedikçe bunları devralır.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Hedef ortamdaki kuruluş ayrıntıları: üyeler, SSO, alan adları, haklar ve son etkinlikler. Bu sayfadan yalnızca kuruluşun durumu değiştirilebilir.',
    'every_workspace_on_this_install_open_one_to_walk_its_pr_4abbea51' => 'Bu kurulumdaki tüm çalışma alanları. Ürünlerini ve ortamlarını incelemek için birini açın. Askıya almak üyelerin oturumlarını kapatır ve sahip olduğu tüm ortamların kimlik doğrulama hizmetini durdurur.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Bu olayları uygulamanız gönderir: olay grubu başına bir çağrı yapılır ve her olay gerçekleştiği kuruluşu belirtir. Geldikçe burada ve ilgili kuruluşun yöneticilerinde görünürler.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Ortamın tüm giriş sayfalarında kullanılabilir. Bir kuruluşa kendi sağlayıcısını ayarlamak için onu seçin; bu sağlayıcı, kuruluşun sayfasında ortam sağlayıcısının yerini alır.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code burada giriş yapmanız için tarayıcınızı açar ve nelere izin vereceğinizi sorar. Güvende tutmanız gereken bir anahtar yoktur. OAuth ile giriş yapan her MCP istemcisi bu URL ile aynı şekilde çalışır.',
    'one_workspace_on_this_install_its_team_its_projects_and_e343ed1c' => 'Bu kurulumdaki bir çalışma alanı: ekibi, projeleri ve bu projelerin tüm ortamları. Askıya almak üyelerin oturumlarını kapatır ve tüm bu ortamların kimlik doğrulama hizmetini durdurur.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Ortam genelinde: bu ortamda hesabı olan herkes, hangi kuruluşta olursa olsun, bu uygulamaya giriş yapabilir. Böyle geniş bir erişim istemiyorsanız bir kuruluş belirtin.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Entra ID, Okta veya Google Workspace ile giriş, Enterprise planında sunulur. Bu kuruluş için etkinleştirmek üzere hesabınızla ilgilenen ekiple iletişime geçin.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Nerelerde oturumunuzun açık olduğu, nelerin sizin adınıza işlem yapabildiği ve hesabınızda neler olduğu. Tanımadığınız bir şey görürseniz ilgili oturumu kapatın ve parolanızı değiştirin.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Son 30 günde kaç kişinin giriş yaptığı ve uygulamalarınızın API’yi ne sıklıkla çağırdığı. Bu bilgiler yükü görmeniz ve anormallikleri fark etmeniz içindir; fatura değildir.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Bu kullanıcı bir kuruluşun sahibi veya yöneticisidir; bu nedenle onun adına oturum açılamaz. Böyle bir hesaba girmek, bunu yapan kişiye kuruluş üzerinde kalıcı kontrol sağlayabilir.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Uygulamalarınızın ve ajanlarınızın diğer hizmetlere sunduğu API anahtarları. Her değer depoda şifrelenir, yalnızca yetki verdiğiniz uygulamalara iletilir ve kaydedildikten sonra bir daha gösterilmez.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Kullanıcılarınızdan biri adına işlem yapmak isteyen uygulamalar. Her kullanıcı kendi isteklerini onaylar. Burada bir isteği yalnızca kötüye kullanım gibi görünüyorsa reddedin; ret kararı denetim günlüğüne kaydedilir.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Verilerin ne sıklıkla çekileceği ve İK sisteminin hangi alanlarının her kişiye kopyalanacağı; örneğin maliyet merkezi veya konum. Alanların değiştirilmesi, sonraki çalıştırmanın tam eşitleme olmasını sağlar.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Bu kuruluşun BT yöneticisine verilen ve hâlâ erişim sağlayan bağlantılar. Birini iptal ettiğinizde hemen çalışmayı durdurur; üzerinden daha önce yapılan ayarlar korunur.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Ajanların bir kullanıcı adına işlem yapma istekleri geldikçe burada görünür. Her kullanıcı kendi isteklerini onaylar; bu sayfa kötüye kullanım gibi görünenleri reddetmek içindir.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'TÜM koşullar sağlandığında Radar bu kuralın eylemini uygular ve sonraki kuralları değerlendirmez. Kurallar, izin ve engelleme listelerinden sonra, yerleşik kurallardan önce değerlendirilir.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Uygulamanızın hizmet verdiği tüm kuruluşlar hakkında gönderdiği denetim olayları, en yeniler önce gösterilir. Her kuruluşun olayları kendi hash zincirini oluşturur.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Kuruluşunuzun kurduğu her şey ve yapılması gerekenler. Kurulum kontrol listesi gerçek durumu izler; bir adım gerçekten tamamlandığı anda otomatik olarak işaretlenir.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Yönetici olarak bir kimlik doğrulama uygulaması veya geçiş anahtarı da ekleyin. Telefon numaranız ele geçirilirse SMS’leriniz de alınabilir; bu yüzden tek ikinci faktörünüz olamaz.',
    'deleting_this_workspace_tears_down_every_project_and_en_f26b2e2f' => 'Bu çalışma alanının silinmesi, sahip olduğu tüm projeleri ve ortamları kaldırır. Canlı kimlik sağlayıcılarını korumak için bu işlem doğrudan yapılamaz; devam etmek üzere destekle iletişime geçin.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Bu kurulumdaki tüm platform sayfalarına erişimi hemen kaybeder ve mevcut oturumları bir sonraki istekte çalışmayı durdurur. Kullanıcıyı buradan yeniden etkinleştirebilirsiniz.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Doğrulanmış alan adları kişileri kendi kimlik sağlayıcınıza yönlendirir; bu özellik Enterprise planına dahildir. Bu kuruluş için etkinleştirmek üzere hesabınızla ilgilenen ekiple iletişime geçin.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'İzin, bir rolün yapabileceği tek bir işlemdir; örneğin fatura oluşturmak veya rapor okumak. Burada kod yazmadan kendi izinlerinizi tanımlayıp rollerde birleştirebilirsiniz. Uygulamalar da izinlerini otomatik kaydedebilir; böylece liste, uygulamanın gerçekten denetlediği kurallarla uyumlu kalır. Oluşturduğunuz izinler size aittir. Ortamın paylaştığı izinleri kullanabilir, ancak değiştiremezsiniz.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Her girişte geçerli olan parola kuralları, hesap kilitleme, iki faktör ve tek oturum açma zorunlulukları. Ortam genelinde geçiş anahtarlarının ve giriş bağlantılarının sunulup sunulmayacağı ve oturum süresi de belirlenir. Ortam, tüm kuruluşların devraldığı temel kuralları tanımlar. Kuruluşlar parola ve iki faktör kurallarını sıkılaştırabilir, ancak gevşetemez.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Bu ortamdaki ajanların bir kişinin izin vermesini beklediği işlemler. Anahtarı bir işlem için onay gerektiren ajan durur ve anahtarı oluşturan kişiye sorar. Bu kişi telefondan veya buradan yanıt verebilir. Ortamı yöneten herkes şüpheli bir isteği reddedebilir. Alt bölümde, kullanıcılar adına işlem yapmak isteyen uygulamaların her kullanıcı tarafından ayrı ayrı onaylanan istekleri bulunur.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Kişinin oturumları ve token’ları iptal edilir. Geçiş anahtarları, ikinci faktörleri, üyelikleri, rol atamaları, API token’ları, kasadaki sırları, cihazları ve bilgilerinin saklanan tüm kopyaları silinir. Hesaptan yalnızca takma kimlikle kaydedilmiş, devre dışı bir kayıt kalır. Buradan kişi senkronize eden uygulamalara kişiyi silmeleri bildirilir. Denetim günlüğü adını veya adresini değil, anlam içermeyen kimliğini korur.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Onayladığınız her şey; oturum açtığınız cihazlar ve komut satırı araçları da buna dahildir.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Kendi sistemlerinizin bu kuruluş için saklaması gereken veriler. Anahtarı olmayan satırlar atlanır.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Kendi kurallarınızdan sonra değerlendirilir. Tetiklenen her kural kaydedilir; kararı en katı kural belirler.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'İletim devam eder. Kapalı olduğu sırada oluşturulan kayıtlar hâlâ beklemededir ve sonraki grupla gönderilir.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'İletim hemen durur ve saklanan kimlik bilgisi yok edilir. Denetim kayıtları değişmeden kalır.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Cbox ID ile diğer sistemler arasındaki tüm bağlantılar tek yerde: tek oturum açma, sosyal hesapla giriş, dizin senkronizasyonu ve İK sistemleri, dışa yönelik hesap sağlama, SAML uygulamaları, webhooklar, hooklar, günlük akışları ve veri kanalları. Katalogdan istediğiniz bağlantının kurulumunu başlatabilirsiniz; her kart ilgili kurulum sayfasını açar. Bağlantılar listesi tüm mevcut bağlantıları ve durumlarını gösterir, hatalı olanları öne alır.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Buradaki tüm giriş yöntemleri — parola, geçiş anahtarı, giriş bağlantısı, sosyal hesap, kurumsal SSO ve ikinci faktör — açık olup olmadıkları ve nereden değiştirildikleriyle birlikte gösterilir. Çoğunu ortam belirler; SSO bağlantıları ise her kuruluşa aittir. Dağıtım düzeyinde bir yöntem kapatılmış veya sınırlanmışsa sayfa bunu ve ilgili ayarı belirtir.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Ajan, bu ortamda yönetim anahtarıyla işlem yapan herhangi bir yazılımdır: Claude Code veya Cursor gibi bir AI asistanı, dahili bot ya da kendi backendiniz. Her birine yalnızca ihtiyaç duyduğu kapsamları içeren ayrı anahtar verin. Hangi işlemlerin onayınızı bekleyeceğini belirleyin ve ajan işi bittiğinde veya şüpheli bir durum olduğunda anahtarı hemen iptal edin.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API, https://api.example.com gibi erişim token’ı alan bir hizmetinizdir. Desteklediği kapsamlarla kaydedin; böylece bu kapsamları verebilirsiniz. Ortamdaki kuruluşların kaydettiği uygulamaların hangi kapsamları isteyebileceğine siz karar verirsiniz. API’ye yönelik token, hizmetinizin doğruladığı hedef kitle olarak API adresini taşır.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Denetim izinin Cbox ID dışına aktarılması: zamanlanmış dışa aktarma, yeni kayıtları her beş dakikada bir SIEM sistemine veya arşive gönderir. Günlük saklama görevi hiçbir veriyi silmeden kontrol noktası oluşturur. GDPR erişim talebi için bir kişinin denetim geçmişini buradan alabilir veya ortam konsolunda dışa aktarmaların çalıştığını kontrol edebilirsiniz.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Platform › Ortamlar bölümünde bir ortam oluşturun; ilgili sayılar burada görünür.',
