    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Kullanıcıların markanızla ilgili gördüğü her şey tek sayfada: barındırılan giriş sayfasının logosu, faviconu, renkleri, yazı tipi ve köşe biçimi canlı önizlemeyle; ayrıca ürün adı, e-posta göndereni ve karşılama e-postası. Ortam için bir kez ayarlayın, tüm kuruluşlar devralsın. İsterseniz bir kuruluşa Marka görünümü sekmesinden ayrı görünüm verebilirsiniz.',
    'each_project_in_your_workspace_has_its_own_plan_and_env_c5ff35b1' => 'Çalışma alanındaki her projenin kendi planı ve ortam kotası vardır. Bunlar, bu ayın kullanımıyla birlikte burada gösterilir: kuruluşlar, ücretlendirilen tek oturum açma bağlantıları ve girişler. Fiyatlandırma aylık aktif kullanıcıları ve SSO ile SCIM gibi kurumsal bağlantıları esas alır. Test ortamlarında bağlantı ücreti alınmaz.',
    'every_api_key_the_people_in_this_organization_have_crea_fe7787a7' => 'Bu kuruluştaki kişilerin kuruluşun uygulamaları için oluşturduğu tüm API anahtarları: sahibi, uygulaması, izinleri ve son kullanımı. Anahtar yalnızca sahibinin yapabildiğini yapabilir ve sahibi kuruluştan ayrıldığında çalışmayı durdurur. Sızan veya kullanılmayan anahtarları iptal edin. Her kişi kendi anahtarlarını Hesabım bölümünde oluşturur.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Başka bir sistemden geçiş sırasında uygulama, Cbox ID’de henüz bulunmayan bir kişinin e-posta ve parolasının eski giriş uç noktasında doğrulanmasını isteyebilir. Onaylamadan önce uç noktayı test edin. Kabul edilen kişi burada oluşturulur ve bir daha eski sisteme gönderilmez. Ancak eski uç nokta çalışmıyorsa henüz taşınmamış kişiler giriş yapamaz.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Uygulamanızın hizmet verdiği her kuruluş için gönderdiği denetim olayları: ürün içinde kimin, neyi, ne zaman yaptığı. Olaylar kuruluş bazında bir özet zincirinde saklanır ve o kuruluşun yöneticilerine gösterilir. Bir kuruluş hesabına ait denetim günlüğünü istediğinde kullanın. Olayları tutarlı tutmak için şemalar tanımlayın.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Gelecekte verilecek hiçbir geçici erişim izni bu sırrı açamaz. İptal hemen uygulanır ve kalıcıdır.',
