    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Bu kuruluşun henüz üyesi yok. Birisi davet edilene veya kullanıcı sağlama yoluyla eklenene kadar kimse kuruluşa giriş yapamaz.',
