    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Anahtarı şimdi kopyalayıp ajana verin. Yalnızca özeti saklandığından anahtar yalnızca bu kez gösterilir.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Kuruluşun sahip olduğu e-posta alan adları; her biri DNS TXT kaydıyla doğrulanır. Alan adı doğrulandıktan sonra zorunlu SSO yönlendirmesini açabilirsiniz. Bu, o alan adında adresi olan herkesi parola yerine kurumsal SSO bağlantısına yönlendirir. Tek oturum açmaya geçmeden önce kullanıcıların adreslerinin bulunduğu tüm alan adlarını doğrulayın.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Uygulamanızın kendi erişim modeli: belge ve klasör gibi kaynak türleri, sahip, düzenleyici ve görüntüleyici gibi ilişkiler ve bunların devralınması. Örneğin bir klasörün görüntüleyicileri içindeki tüm belgeleri okuyabilir. Uygulama kimin hangi kaynakla nasıl ilişkili olduğunu kaydeder ve her istekte kullanıcının belgeyi düzenleyip düzenleyemeyeceğini sorar. Yanıtı şema belirler.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Bu ortam, REST API’nin yanında AI asistanlarının araç çağırmak için kullandığı standart yöntem olan MCP sunucusunu sunar. Adresi ve yönetim anahtarını Claude Code, Cursor veya başka bir MCP istemcisine yapıştırın. Ajan, konsoldaki aynı denetimler ve denetim günlüğüyle yalnızca anahtar kapsamlarının izin verdiği işlemleri yapabilir.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Anahtar, kendi betiklerinizin ve entegrasyonlarınızın giriş yapmadan sizin adınıza bir uygulamanın API’sini çağırmasını sağlar. Yalnızca sizin o uygulamada yapabildiklerinizi yapabilir. Erişiminiz azaltılırsa anahtar da aynı erişimi kaybeder. Anahtar yalnızca bir kez gösterilir. Oluştururken kopyalayın; sızarsa veya artık kullanılmıyorsa hemen iptal edin.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Kullanıcı sağlama durur ve grup eşlemeleri kaldırılır. Oluşturulan kullanıcılar kalır.',
