    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooklar, bağlı uygulamalara çıkış bildirimleri, bu uygulamalardan alınan rol güncellemeleri ve kuyruktaki e-postalar, kullanıcı beklerken değil arka plandaki kuyruk işçileri tarafından işlenir. Çalışan işçi yoksa hiçbir şey gönderilmez; konsolun geri kalanı ise normal görünebilir. Bu sorunu burada görebilirsiniz.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Kimin hangi role sahip olduğunu ve hâlâ ihtiyaç duyup duymadığını kontrol ettiğiniz inceleme. Kişiler ekip değiştirip eski izinlerini korudukça erişim fark edilmeden birikir. İnceleme bu erişimleri temizlemenizi sağlar. İptaller incelemeyi kapattığınızda uygulanır; tüm süreç denetçiniz için kaydedilir.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Uygulama daha sonra farklı bir URL bildirirse bu onay kaldırılır ve yeniden istenir. Parolaların gönderildiği adresin değişmesi yeni onay gerektirir. Devredilen giriş geçici bir çözümdür: eski sistemde az sayıda kişi kaldığında kapatın ve o gruba parola sıfırlama iletileri gönderin.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Kullanıcıların burada ayrı bir parola yerine Microsoft Entra ID, Okta veya Google Workspace gibi mevcut şirket hesaplarıyla giriş yapmasını sağlar. Kimlik sağlayıcınızı bir kez bağlayın ve e-posta alan adlarınızı doğrulayın. Bu alan adlarındaki herkes daha sonra giriş için sağlayıcıya yönlendirilir.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Hangi kuruluşlara üye olursa olsun, bu ortamda kimliği bulunan herkes. Parolasını veya ikinci faktörünü sıfırlamak, oturumlarını kapatmak, hesabını devre dışı bırakmak, kuruluş ve rollerini değiştirmek ya da silinme hakkı talebi üzerine kalıcı olarak silmek için kişiyi açın.',
