    'how_workspace_owners_and_operators_sign_in_to_cbox_id_i_293f421d' => 'Çalışma alanı sahiplerinin ve operatörlerinin Cbox ID’ye nasıl giriş yapacağı platform ortamının konsolunda ayarlanır.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Bu genişletme noktaları işlemden sonra değil, işlem sırasında çalışır ve yanıtları sonucu değiştirir: uç noktanız bir belirtece bilgi ekleyebilir veya oturum açmayı reddedebilir. İşlemin yürütülmesine doğrudan katıldıkları için yavaş veya çalışmayan bir uç nokta, oturum açmaya çalışan kişiyi etkiler.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Kimlik sağlayıcınız SCIM standardı üzerinden burada kişileri kendiliğinden oluşturur, günceller ve devre dışı bırakır. İK sistemindeki işe giriş veya ayrılış kaydı, destek talebi ve geride kalan hesap olmadan saniyeler içinde uygulamalara ulaşır. Bu, özellikle birisi ayrıldığında önemlidir.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Bu ortamdaki kuruluşların, kullanıcıların, tek oturum açma bağlantılarının, uygulamaların ve kullanıcı eşitlemelerinin sayıları; her biri kendi sayfasına bağlanır. Alttaki kısayollar en sık yapılan oluşturma işlemlerini başlatır: kuruluş, kullanıcı, tek oturum açma bağlantısı veya uygulama oluşturma.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Rol, uygulamalarınızın anladığı bir görev tanımıdır; örneğin “Editör” veya “Destek görevlisi”. Kimin hangi role sahip olduğunu burada belirlersiniz; her uygulama kendi rollerinin hangi işlemlere izin verdiğine kendisi karar verir. Roller kişiyi bağlı tüm uygulamalarda izler, böylece erişimi tek yerden verir ve geri alırsınız.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Her denetim günlüğü kaydını yazıldığı anda güvenlik ekibinizin SIEM gibi araçlarına kopyalar. İncelemelerin dışa aktarma talebi beklemeden ekibinizin zaten kullandığı araçlarda başlaması için bir hedef ayarlayın. Teslim en az bir kez gerçekleşir; bu nedenle zaman zaman yinelenen kayıtlar olabilir.',
    'a_workspace_appears_here_the_moment_somebody_signs_up_o_ce907423' => 'Birisi kaydolduğunda çalışma alanı burada görünür. Yukarıdaki Yeni çalışma alanı seçeneğiyle kendiniz de oluşturabilirsiniz.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Bu kuruluştaki kişilerin e-posta adreslerinde kullandığı alan adını ekleyin, TXT kaydını yayımlayın ve alan adını doğrulayın.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Ekibinizi otomatik olarak SSO’ya yönlendirmek için e-posta alan adının sahipliğini doğrulayın.',
