    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Meta veri şemaları, JSON Schema standardının bir alt kümesidir: özellikleri metin, sayı, tam sayı, mantıksal değer veya null olabilen; izin verilen değer listelerini ve uzunluk, aralık, desen ve biçim kısıtlarını destekleyen bir nesne. Değişiklik kaydedildiğinde yeni bir sürüm oluşur; önceden kaydedilmiş olaylar, doğrulandıkları sürümü korur.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Her bağlantı, kişilerin GitHub, Google veya Slack gibi bir hizmetteki kendi hesaplarını bağlamasını sağlar. Belirteçleri burada şifrelenerek saklanır ve güncel tutulur. Yetkilendirdiğiniz uygulamalar, kişi adına hizmeti her çağırdığında geçerli bir belirteç ister; belirteci kendileri saklamaz.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Yönetim ve destek rolü, destek veya operasyon ekipleri gibi kendi çalışanlarınıza tüm ortam genelinde verdiğiniz bir roldür. Her kuruluşta geçerlidir; kuruluş yöneticileri bu rolü göremez, veremez veya kaldıramaz. Bir uygulamanın kendi rolü bu şekilde verilirse yalnızca o uygulamada geçerli olur.',
    'an_environment_is_a_fully_isolated_identity_service_wit_fed9a3d8' => 'Ortam; kendi kullanıcıları, anahtarları, oturum açma sistemi ve düzenleyicisi olan, tamamen yalıtılmış bir kimlik hizmetidir. Bu kurulumdaki tüm ortamlar, sahibi olan çalışma alanıyla birlikte burada listelenir. Bir ortam oluşturun, konsolda bu ortamı seçin ve ilk kuruluşu ve yöneticiyi ekleyin.',
