    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Kimlik doğrulama uygulaması yüklü bir telefon, onay isteklerine yanıt vermenizi sağlar ve birisi hesabınızda oturum açtığında sizi bilgilendirir. Kodu tarayarak bir kez kaydedin. Telefonu kaybederseniz hemen buradan kaldırın; böylece artık hiçbir isteği onaylayamaz.',
    'a_workspace_is_one_signed_up_company_s_home_on_this_ins_3053f712' => 'Çalışma alanı, bu kuruluma kaydolmuş bir şirketin projelerini, ortamlarını ve ekibini barındıran alanıdır. Ürünlerini ve ortamlarını incelemek için açın veya askıya alın: askıya alma, üyelerin oturumlarını kapatır ve sahip olduğu tüm ortamlarda oturum açmayı durdurur.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Bir uygulama veya AI ajanı sizin adınıza işlem yapmak için onayınıza ihtiyaç duyduğunda, bunu her zaman önünüzdeki ekranda soramaz; bunun yerine burada sorar. Yalnızca sizin başlattığınız istekleri onaylayın ve gösterilen kodun isteği gönderen cihazdaki kodla eşleştiğini kontrol edin.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Proje, kendi planı, oturum açma sistemi ve üretim veya hazırlık gibi ortamları olan ürünlerinizden biridir. Yönetmek istediğiniz ortamı buradan açın. Ayrı faturalandırılması ve işletilmesi gereken bir ürün başlatırken yeni proje oluşturun.',
