    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Kişileri Cbox ID üzerinden oturum açtıran veya API’sini çağıran her uygulama burada kaydedilir ve kendi kimlik bilgilerini alır. Her uygulama ve ortam için ayrı kayıt oluşturun. Kimlik bilgilerini aralarında paylaşmayın; böylece birini iptal ettiğinizde diğerleri çalışmaya devam eder.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Kuruluşu adına veya tanıtıcısına, kullanıcıyı adına veya e-posta adresine göre bu kurulumdaki tüm ortamlarda arar; yalnızca konsolda seçili ortamla sınırlı değildir. Birisi yardım istediğinde hangi ortamda olduğunu bilmiyorsanız kullanın.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Uygulamayı kullanıcılarından birinin gördüğü gibi görün: belirttiğiniz bir gerekçeyle, en fazla bir saatliğine o kişinin adına oturum açarsınız. Uygulamaya gerçekte kimin işlem yaptığı bildirilir ve oturumu sürdürme olanağı verilmez. Kuruluşun denetim günlüğü bunu kimin, neden yaptığını kaydeder.',
    'a_project_is_one_idp_product_this_workspace_owns_and_it_a5e40dff' => 'Proje, bu çalışma alanının sahip olduğu bir IdP ürünüdür ve ortamlar projeye bağlıdır. Çalışma alanı kendi konsolundan proje oluşturana kadar burada seçilecek veya açılacak bir ortam yoktur. Bu ekran çalışma alanı adına proje oluşturmaz.',
