    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Her kuruluş, ürününüzü kullanan ve kendi üyeleri, rolleri, alan adları ve tek oturum açma yapılandırması olan bir şirket veya ekiptir. Kaydolan her şirket için bir kuruluş oluşturun. Üyelerini, davetlerini ve doğrulanmış alan adlarını yönetmek veya kuruluşu askıya almak için açın.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID, bir üyenin katılması veya bir rolün değişmesi gibi olaylardan sonra uç noktanıza imzalı mesaj gönderir; böylece sistemleriniz düzenli sorgulama yapmadan tepki verebilir. Başarısız teslimler yeniden denenir. Olay zaten gerçekleşmiştir: uç noktaya bilgi verilir, sonucu belirleme hakkı verilmez.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Şema, bir eylemin olaylarının yapısını tanımlar: hangi hedef türlerini belirttiklerini ve meta verilerinin neler içerdiğini. Şeması olan eylemlerin olayları geldiklerinde denetlenir. Şema yoksa katı mod açık olmadığı sürece gönderildikleri haliyle kabul edilir.',
    'everyone_who_administers_this_workspace_the_built_in_ro_26825e5f' => 'Bu çalışma alanını yöneten herkes, sahip oldukları yerleşik rol — Sahip, Yönetici, Geliştirici, Üye veya Görüntüleyici — ve erişebildikleri ortamlar. Kişileri e-postayla davet edin ve her kişiye yalnızca işi için gerekli ortamları verin.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Uygulamalarınızı kullanan kişilerin kendi GitHub, Google, Slack veya Salesforce hesaplarını bağlamasına izin verin; böylece uygulamalar bu API’leri onların adına çağırabilir. Belirteçler burada şifrelenerek saklanır, yenilenir ve yalnızca yetkilendirdiğiniz uygulamalara geçici olarak verilir.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'Davet edilen kişi e-postayla kabul eder. Kimse onayı olmadan kuruluşa eklenmez.',
    'this_user_has_no_signed_in_sessions_right_now_they_appe_0ac73d09' => 'Bu kullanıcının şu anda açık oturumu yok. Kullanıcı giriş yaptığında oturumları burada görünür.',
