    'user_created_they_have_no_way_to_sign_in_until_you_send_a612f0b1' => 'Kullanıcı oluşturuldu. Bağlantı gönderene kadar oturum açamaz.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Kullanıcı verileri silindi. Hesap takma adlandırıldı ve silme işlemi denetim günlüğüne user.erased olarak kaydedildi.',
    'platform_operators_administer_every_workspace_and_envir_fb24c050' => 'Platform operatörleri, bu kurulumdaki tüm çalışma alanlarını ve ortamları her birinin üzerindeki bir düzeyden yönetir. Yalnızca kurulumun işletilmesinden sorumlu kişileri operatör olarak ekleyin ve bu görevleri bittiğinde hesaplarını askıya alın.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Konsolda seçili ortamdaki tüm kuruluşlar; bayiler, yönettikleri kuruluşlar ve alt birimleri içeren bir ağaçta gösterilir. Burada kuruluş oluşturabilir, askıya alabilir veya başka bir üst kuruluşun altına taşıyabilirsiniz.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Kurulum başka bir aralık belirlemediyse son 30 güne ait oturum açmalar, verilen belirteçler, yeni kullanıcılar ve iki faktörlü kimlik doğrulama kayıtları gün gün gösterilir. Kurulumu işleten kişi analiz verilerinin saklanacağı yeri yapılandırana kadar sayfa boş kalır.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Bunu rolün güven politikası olarak ayarlayın (IAM › Roles › Trust relationships). Platform yalnızca bu akışın harici kimliğini sunduğunda rolü üstlenebilir; böylece platformdaki başka biri kendi akışını sizin rolünüze yönlendiremez.',
