    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'Bu bağlantı üzerinden hangi kuruluşun kullanıcılarının giriş yaptığı. Alan adları ve Yönetici Portalı bağlantısı o kuruluşun sayfasındadır.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Hesabınızda oturum açmış tüm tarayıcı ve cihazlar, adınıza işlem yapmasına izin verdiğiniz uygulamalar, son oturum açmalar ve güvenlik değişiklikleri. Tanımadığınız bir etkinlik varsa ilgili oturumu kapatın veya uygulamanın erişimini geri alın, ardından parolanızı değiştirin.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Bu kuruluştaki her değişiklik: kimin, neyi, hangi nesnede ve ne zaman yaptığı. Kayıtlar özet değerleriyle zincirlenir; bir kaydın silinmesi veya değiştirilmesi zinciri bozar ve tespit edilir. Bilerek salt okunurdur; denetçiye sunacağınız kayıt budur.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Neredeyse tüm sağlayıcılar için boş bırakın: ID belirteçleri, keşif belgesinde yayımlanan imzalama anahtarlarıyla (jwks_uri) doğrulanır ve anahtar yenilemeleri de izlenir. Sağlayıcının PEM açık anahtarını yalnızca sağlayıcı anahtar yayımlamıyorsa yapıştırın.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Cbox ID’nin işaretleyecek kadar riskli bulduğu oturum açmalar ve istekler; en yenisi önce, risk puanı ve gerekçeleriyle gösterilir. Başarısız oturum açmalar arttığında veya birisi kendisinin yapmadığı bir oturum açma bildirdiğinde burayı inceleyin.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Bu ortam REST API’sinin yanında bir MCP sunucusu sunar. Bir ajanı yönetim anahtarıyla bağlayın; ajan, konsolla aynı denetimler, onaylar ve denetim günlüğüyle yalnızca anahtarın kapsamlarının izin verdiği işlemleri yapabilir.',
    'nothing_recorded_matches_these_filters_widen_the_range_804705cd' => 'Bu filtrelerle eşleşen kayıt yok. Aralığı genişletin veya bir filtreyi kaldırın.',
