    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Şu anda bu kullanıcı olarak kimlerin oturum açtığı. Girişe neden izin verildiği, ek doğrulama istendiği veya girişin engellendiği Radar’da gösterilir.',
    'what_this_organization_s_sign_in_is_wired_to_read_from_cde71601' => 'Gerçek yapılandırmaya göre bu kuruluşun giriş sisteminin nereye bağlı olduğu.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Kuruluşun kendi sağlayıcısı, o kuruluşun oturum açma sayfasında ortamın sağlayıcısının yerini alır. Ortamın sağlayıcısını kapatan kuruluşlar da listelenir. Bu yalnızca sayfadaki düğmeyi kaldırır; o yöntemle erişimi engelleyen, SSO’nun zorunlu tutulmasıdır.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Kendi kullanıcı listesini tutan uygulamalar, birisi katıldığı veya ayrıldığı anda güncelliğini kaybeder. SCIM bağlantısı her değişikliği gerçekleştiğinde bu uygulamalara iletir; en kolay unutulan ayrılışlar da buna dahildir.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Bir kimlik sağlayıcısını SCIM uç noktamıza yönlendirin, Google Workspace veya Microsoft Entra’yı ya da İK sisteminizi — Workday, BambooHR, Rippling, HiBob veya Personio — bağlayın. Kişi verilerini belirli aralıklarla alırız.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Denetim kaydı burada, güvenlik ekibinizin araçları ise başka yerdedir. Bir akış, her kaydı yazıldığı anda bu araçlara kopyalar; böylece inceleme, sizden CSV dışa aktarımı istenerek başlamaz.',
