    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Ortam tamamen yalıtılmıştır; kendi kullanıcıları, anahtarları, oturum açma sistemi ve düzenleyicisi vardır. Yukarıda ilk ortamı oluşturun, ardından kuruluş ve yönetici ekleyin.',
